package watch

import (
	"sync"
	"time"
)

// engine is the pure per-library trigger state machine (D3): every
// decision runs over an explicit now — no clock, no goroutines, no I/O —
// so the debounce/refire policy is table-tested with synthetic times.
// State is keyed per library: distinct libraries never share anything.
// The mutex exists because D3's dispatch law runs completed on the scan
// goroutine while the Run loop observes concurrently — the DECISION
// stays sequential; only its bookkeeping is shared.
type engine struct {
	mu       sync.Mutex
	debounce time.Duration
	libs     map[int64]*trigger
}

// trigger is one library's quiet-window state. A zero deadline is the
// disarmed position — no scan pending until the next event or backstop.
type trigger struct {
	running  bool
	dirty    bool
	deadline time.Time
}

func newEngine(debounce time.Duration) *engine {
	return &engine{debounce: debounce, libs: make(map[int64]*trigger)}
}

func (e *engine) trig(id int64) *trigger {
	t, ok := e.libs[id]
	if !ok {
		t = &trigger{}
		e.libs[id] = t
	}
	return t
}

// observe records a filesystem event for library id at now: an idle
// library extends its quiet-window deadline (the debounce coalesces a
// burst of writes into the one scan at expiry); a library whose scan is
// running is marked dirty instead — completed turns that into one
// trailing scan.
func (e *engine) observe(now time.Time, id int64) {
	e.mu.Lock()
	defer e.mu.Unlock()
	t := e.trig(id)
	if t.running {
		t.dirty = true
		return
	}
	t.deadline = now.Add(e.debounce)
}

// dueFires reports whether library id's quiet window has expired at now
// with no scan running, arming the library so exactly one true is
// reported per window — the caller fires Deps.Scan once and the library
// stays armed (running) until completed.
func (e *engine) dueFires(now time.Time, id int64) bool {
	e.mu.Lock()
	defer e.mu.Unlock()
	t := e.trig(id)
	if t.running || t.deadline.IsZero() || now.Before(t.deadline) {
		return false
	}
	t.running = true
	return true
}

// backstop arms library id for an immediate scan at the reconcile tick:
// an idle library is armed and the caller dispatches (true); a library
// whose scan is running is marked dirty instead — completed turns that
// into one trailing scan (the trailing-scan law).
func (e *engine) backstop(id int64) bool {
	e.mu.Lock()
	defer e.mu.Unlock()
	t := e.trig(id)
	if t.running {
		t.dirty = true
		return false
	}
	t.running = true
	t.deadline = time.Time{}
	return true
}

// nextDeadline reports the earliest pending quiet-window deadline across
// idle libraries — the adapter's timer target. A library that is running
// or disarmed contributes nothing.
func (e *engine) nextDeadline() (time.Time, bool) {
	e.mu.Lock()
	defer e.mu.Unlock()
	var best time.Time
	found := false
	for _, t := range e.libs {
		if t.running || t.deadline.IsZero() {
			continue
		}
		if !found || t.deadline.Before(best) {
			best, found = t.deadline, true
		}
	}
	return best, found
}

// completed clears library id's running scan at now. When the scan
// failed (ok false — the failure re-arms so a lost scan converges) or
// events arrived mid-run (dirty), the quiet window re-arms for one
// trailing scan; a clean successful run disarms, leaving the next event
// or reconcile tick to trigger again.
func (e *engine) completed(now time.Time, id int64, ok bool) {
	e.mu.Lock()
	defer e.mu.Unlock()
	t := e.trig(id)
	t.running = false
	if !ok || t.dirty {
		t.deadline = now.Add(e.debounce)
	} else {
		t.deadline = time.Time{}
	}
	t.dirty = false
}
